def call(problem, ns, inp):
    root = build_tree(inp["root"])
    def find(n, v):
        while n and n.val != v:
            n = n.left if v < n.val else n.right
        return n
    ans = ns["Solution"]().lowestCommonAncestor(root, find(root, inp["p"]), find(root, inp["q"]))
    return ans.val if ans is not None else None
